#include <torch/extension.h>
torch::Tensor conv_transpose3d_s1_forward(torch::Tensor x,
                                          torch::Tensor w,
                                          c10::optional<torch::Tensor> b,
                                          int64_t stride,
                                          int64_t padding,
                                          int64_t output_padding,
                                          int64_t groups);
