cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

// Single fused ConvTranspose3d kernel for the common case used by Model:
//   stride=1, dilation=1, groups=1, square kernel KxKxK.
// Cooperative tiled kernel:
//   block = one batch n, one output-channel tile (8), one 8x8x8 output-spatial tile.
//   For each input channel, the needed input halo is staged in shared memory and
//   reused across all 8 output channels in the tile.
template <typename T>
__global__ void conv_transpose3d_s1_kernel(
    const T* __restrict__ X,
    const T* __restrict__ W,
    const T* __restrict__ B,
    T* __restrict__ Y,
    int N, int Cin, int Cout,
    int Din, int Hin, int Win,
    int Dout, int Hout, int Wout,
    int K, int pad,
    int td, int th, int tw,
    int halo,
    int64_t sXn, int64_t sXc, int64_t sXd, int64_t sXh,
    int64_t sYn, int64_t sYc, int64_t sYd, int64_t sYh,
    int64_t sWi, int64_t sWo, int64_t sWd, int64_t sWh)
{
  constexpr int Threads  = 128;
  constexpr int Tile     = 8;
  constexpr int PVec     = 4;    // Tile^3 / Threads = 512 / 128
  constexpr int CoTile   = 8;

  const int tid = threadIdx.x;
  const int n   = blockIdx.z;
  const int co_base = blockIdx.y * CoTile;

  const int tile_id = blockIdx.x;
  const int tiles_hw = th * tw;
  const int od_t = tile_id / tiles_hw;
  const int rem  = tile_id - od_t * tiles_hw;
  const int oh_t = rem / tw;
  const int ow_t = rem - oh_t * tw;

  const int od_base = od_t * Tile;
  const int oh_base = oh_t * Tile;
  const int ow_base = ow_t * Tile;

  const int halo2 = halo * halo;
  const int halo3 = halo2 * halo;
  const int k2 = K * K;
  const int k3 = k2 * K;

  extern __shared__ float smem_raw[];
  float* sS_ptr = smem_raw;
  float* sW_ptr = smem_raw + halo3;

  Tensor sS = make_tensor(
      make_smem_ptr(sS_ptr),
      make_shape(halo, halo, halo),
      make_stride(halo2, halo, Int<1>{})
  );

  Tensor sW = make_tensor(
      make_smem_ptr(sW_ptr),
      make_shape(Int<CoTile>{}, k3),
      make_stride(k3, Int<1>{})
  );

  Tensor mX = make_tensor(
      make_gmem_ptr(X + (int64_t)n * sXn),
      make_shape(Cin, Din, Hin, Win),
      make_stride(sXc, sXd, sXh, Int<1>{})
  );

  Tensor mY = make_tensor(
      make_gmem_ptr(Y + (int64_t)n * sYn),
      make_shape(Cout, Dout, Hout, Wout),
      make_stride(sYc, sYd, sYh, Int<1>{})
  );

  Tensor mW = make_tensor(
      make_gmem_ptr(W),
      make_shape(Cin, Cout, K, K, K),
      make_stride(sWi, sWo, sWd, sWh, Int<1>{})
  );

  Tensor mB = make_tensor(
      make_gmem_ptr(B),
      make_shape(Cout),
      make_stride(Int<1>{})
  );

  const int in_od_origin = od_base + pad - (K - 1);
  const int in_oh_origin = oh_base + pad - (K - 1);
  const int in_ow_origin = ow_base + pad - (K - 1);

  int od[PVec], oh[PVec], ow[PVec];
  int dz[PVec], dy[PVec], dx[PVec];
  bool pvalid[PVec];

  #pragma unroll
  for (int i = 0; i < PVec; ++i) {
    int p = tid + i * Threads;      // [0, 512)
    int z = p / (Tile * Tile);
    int r = p - z * (Tile * Tile);
    int y = r / Tile;
    int x = r - y * Tile;

    dz[i] = z;
    dy[i] = y;
    dx[i] = x;

    od[i] = od_base + z;
    oh[i] = oh_base + y;
    ow[i] = ow_base + x;

    pvalid[i] = (od[i] < Dout) && (oh[i] < Hout) && (ow[i] < Wout);
  }

  float acc[CoTile][PVec];

  #pragma unroll
  for (int cc = 0; cc < CoTile; ++cc) {
    int co = co_base + cc;
    float bval = 0.0f;
    if (B != nullptr && co < Cout) {
      bval = (float)mB(co);
    }
    #pragma unroll
    for (int i = 0; i < PVec; ++i) {
      acc[cc][i] = bval;
    }
  }

  for (int ci = 0; ci < Cin; ++ci) {
    // Stage the input halo for this input channel.
    for (int idx = tid; idx < halo3; idx += Threads) {
      int hd = idx / halo2;
      int r  = idx - hd * halo2;
      int hh = r / halo;
      int hw = r - hh * halo;

      int id = in_od_origin + hd;
      int ih = in_oh_origin + hh;
      int iw = in_ow_origin + hw;

      float v = 0.0f;
      if ((unsigned)id < (unsigned)Din &&
          (unsigned)ih < (unsigned)Hin &&
          (unsigned)iw < (unsigned)Win) {
        v = (float)mX(ci, id, ih, iw);
      }
      sS(hd, hh, hw) = v;
    }

    // Stage this input channel's weights for the output-channel tile.
    const int w_items = CoTile * k3;
    for (int idx = tid; idx < w_items; idx += Threads) {
      int cc = idx / k3;
      int kk = idx - cc * k3;
      int kd = kk / k2;
      int rr = kk - kd * k2;
      int kh = rr / K;
      int kw = rr - kh * K;

      int co = co_base + cc;
      float v = 0.0f;
      if (co < Cout) {
        v = (float)mW(ci, co, kd, kh, kw);
      }
      sW(cc, kk) = v;
    }

    __syncthreads();

    // Consume staged input halo and weights.
    #pragma unroll
    for (int i = 0; i < PVec; ++i) {
      if (!pvalid[i]) continue;

      for (int kd = 0; kd < K; ++kd) {
        int ld = dz[i] + (K - 1 - kd);
        for (int kh = 0; kh < K; ++kh) {
          int lh = dy[i] + (K - 1 - kh);
          for (int kw = 0; kw < K; ++kw) {
            int lw = dx[i] + (K - 1 - kw);
            float xv = sS(ld, lh, lw);
            int kk = (kd * K + kh) * K + kw;

            #pragma unroll
            for (int cc = 0; cc < CoTile; ++cc) {
              acc[cc][i] += xv * sW(cc, kk);
            }
          }
        }
      }
    }

    __syncthreads();
  }

  #pragma unroll
  for (int cc = 0; cc < CoTile; ++cc) {
    int co = co_base + cc;
    if (co >= Cout) continue;

    #pragma unroll
    for (int i = 0; i < PVec; ++i) {
      if (!pvalid[i]) continue;
      mY(co, od[i], oh[i], ow[i]) = static_cast<T>(acc[cc][i]);
    }
  }
}

torch::Tensor conv_transpose3d_s1_forward(torch::Tensor x,
                                          torch::Tensor w,
                                          c10::optional<torch::Tensor> b,
                                          int64_t stride,
                                          int64_t padding,
                                          int64_t output_padding,
                                          int64_t groups) {
  TORCH_CHECK(x.is_cuda(), "x must be CUDA");
  TORCH_CHECK(w.is_cuda(), "w must be CUDA");
  if (b.has_value()) TORCH_CHECK(b.value().is_cuda(), "bias must be CUDA if provided");

  TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");
  TORCH_CHECK(w.scalar_type() == at::kFloat, "w must be float32");
  if (b.has_value()) TORCH_CHECK(b.value().scalar_type() == at::kFloat, "bias must be float32");

  TORCH_CHECK(x.dim() == 5, "x must be [N, Cin, Din, Hin, Win]");
  TORCH_CHECK(w.dim() == 5, "w must be [Cin, Cout, K, K, K] for groups=1 ConvTranspose3d");
  TORCH_CHECK(stride == 1, "custom CUTE kernel supports stride=1");
  TORCH_CHECK(groups == 1, "custom CUTE kernel supports groups=1");
  TORCH_CHECK(padding >= 0, "padding must be >= 0");
  TORCH_CHECK(output_padding == 0, "custom CUTE kernel supports output_padding=0");

  auto x_c = x.contiguous();
  auto w_c = w.contiguous();

  const int64_t N   = x_c.size(0);
  const int64_t Cin = x_c.size(1);
  const int64_t Din = x_c.size(2);
  const int64_t Hin = x_c.size(3);
  const int64_t Win = x_c.size(4);

  TORCH_CHECK(w_c.size(0) == Cin, "w.size(0) must equal Cin");
  const int64_t Cout = w_c.size(1);
  const int64_t Kd = w_c.size(2);
  const int64_t Kh = w_c.size(3);
  const int64_t Kw = w_c.size(4);
  TORCH_CHECK(Kd == Kh && Kh == Kw, "kernel must be square/cubic");
  const int64_t K = Kd;
  TORCH_CHECK(K >= 1 && K <= 15, "kernel size supported range is [1, 15]");

  const int64_t Dout = (Din - 1) - 2 * padding + K + output_padding;
  const int64_t Hout = (Hin - 1) - 2 * padding + K + output_padding;
  const int64_t Wout = (Win - 1) - 2 * padding + K + output_padding;
  TORCH_CHECK(Dout > 0 && Hout > 0 && Wout > 0, "invalid transposed-conv output size");

  torch::Tensor b_c;
  const float* b_ptr = nullptr;
  if (b.has_value()) {
    b_c = b.value().contiguous();
    TORCH_CHECK(b_c.dim() == 1 && b_c.size(0) == Cout, "bias must be [Cout]");
    b_ptr = b_c.data_ptr<float>();
  }

  auto y = torch::empty({N, Cout, Dout, Hout, Wout}, x_c.options());

  constexpr int Threads = 128;
  constexpr int Tile = 8;
  constexpr int CoTile = 8;

  const int64_t halo = Tile + K - 1;
  const int64_t halo3 = halo * halo * halo;
  const int64_t k3 = K * K * K;
  const int64_t smem_bytes = (halo3 + CoTile * k3) * (int64_t)sizeof(float);
  TORCH_CHECK(smem_bytes <= 96 * 1024, "required dynamic shared memory is too large");

  const int64_t td = (Dout + Tile - 1) / Tile;
  const int64_t th = (Hout + Tile - 1) / Tile;
  const int64_t tw = (Wout + Tile - 1) / Tile;
  const int64_t sp_tiles = td * th * tw;
  const int64_t co_tiles = (Cout + CoTile - 1) / CoTile;

  TORCH_CHECK(sp_tiles <= INT32_MAX, "too many spatial tiles");
  TORCH_CHECK(co_tiles <= 65535, "too many output-channel tiles");
  TORCH_CHECK(N <= 65535, "batch too large for this simple grid mapping");

  dim3 block(Threads);
  dim3 grid((unsigned)sp_tiles, (unsigned)co_tiles, (unsigned)N);

  const int64_t sXn = Cin * Din * Hin * Win;
  const int64_t sXc = Din * Hin * Win;
  const int64_t sXd = Hin * Win;
  const int64_t sXh = Win;

  const int64_t sYn = Cout * Dout * Hout * Wout;
  const int64_t sYc = Dout * Hout * Wout;
  const int64_t sYd = Hout * Wout;
  const int64_t sYh = Wout;

  const int64_t sWi = Cout * Kd * Kh * Kw;
  const int64_t sWo = Kd * Kh * Kw;
  const int64_t sWd = Kh * Kw;
  const int64_t sWh = Kw;

  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();

  cudaError_t attr_err = cudaFuncSetAttribute(
      conv_transpose3d_s1_kernel<float>,
      cudaFuncAttributeMaxDynamicSharedMemorySize,
      (int)smem_bytes);
  TORCH_CHECK(attr_err == cudaSuccess, "cudaFuncSetAttribute failed: ", cudaGetErrorString(attr_err));

  conv_transpose3d_s1_kernel<float><<<grid, block, (size_t)smem_bytes, stream>>>(
      x_c.data_ptr<float>(),
      w_c.data_ptr<float>(),
      b_ptr,
      y.data_ptr<float>(),
      (int)N, (int)Cin, (int)Cout,
      (int)Din, (int)Hin, (int)Win,
      (int)Dout, (int)Hout, (int)Wout,
      (int)K, (int)padding,
      (int)td, (int)th, (int)tw,
      (int)halo,
      sXn, sXc, sXd, sXh,
      sYn, sYc, sYd, sYh,
      sWi, sWo, sWd, sWh
  );

  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "conv_transpose3d_s1_kernel launch failed: ", cudaGetErrorString(err));

  return y;
}
"""

cute_conv_transpose3d_ext = load_inline(
    name="cute_conv_transpose3d_s1_ext",
    cpp_sources=cpp_decl,
    cuda_sources=cuda_src,
    functions=["conv_transpose3d_s1_forward"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=[
        "/root/cutegen_test/cutegen/cutlass/include",
        "/root/cutegen_test/cutegen/cutlass/include/cute/",
    ],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    ConvTranspose3d with square input and square kernel, implemented by one custom
    cooperative-tiled CUTE/CUDA kernel in forward().
    """
    def __init__(self,
                 in_channels: int,
                 out_channels: int,
                 kernel_size: int,
                 stride: int = 1,
                 padding: int = 0,
                 output_padding: int = 0,
                 groups: int = 1,
                 bias: bool = False):
        super().__init__()
        assert isinstance(kernel_size, int) and kernel_size >= 1
        assert isinstance(stride, int) and stride >= 1
        assert isinstance(padding, int) and padding >= 0
        assert isinstance(output_padding, int) and output_padding >= 0
        assert isinstance(groups, int) and groups >= 1

        self.in_channels = int(in_channels)
        self.out_channels = int(out_channels)
        self.kernel_size = int(kernel_size)
        self.stride = int(stride)
        self.padding = int(padding)
        self.output_padding = int(output_padding)
        self.groups = int(groups)

        if self.stride != 1:
            raise ValueError("ModelNew custom CUTE kernel supports stride=1 only")
        if self.groups != 1:
            raise ValueError("ModelNew custom CUTE kernel supports groups=1 only")
        if self.output_padding != 0:
            raise ValueError("ModelNew custom CUTE kernel supports output_padding=0 only")

        k = self.kernel_size
        self.weight = nn.Parameter(torch.empty(self.in_channels, self.out_channels, k, k, k))
        if bias:
            self.bias = nn.Parameter(torch.empty(self.out_channels))
        else:
            self.register_parameter("bias", None)

        self.reset_parameters()
        self._ext = cute_conv_transpose3d_ext

    def reset_parameters(self):
        init.kaiming_uniform_(self.weight, a=math.sqrt(5))
        if self.bias is not None:
            fan_in = self.in_channels * self.kernel_size ** 3
            bound = 1.0 / math.sqrt(fan_in) if fan_in > 0 else 0.0
            init.uniform_(self.bias, -bound, bound)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self._ext.conv_transpose3d_s1_forward(
            x.contiguous(),
            self.weight.contiguous(),
            self.bias if self.bias is not None else None,
            int(self.stride),
            int(self.padding),
            int(self.output_padding),
            int(self.groups),
        )

